<script setup lang="ts">import{ref}from'vue';import{Head,router}from'@inertiajs/vue3';import{CalendarRange,ClockAlert,FileSpreadsheet,UserCheck}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';const p=defineProps<{rows:any[],month:string}>();const month=ref(p.month);const load=()=>router.get('/dashboard/pegawai/laporan',{month:month.value},{preserveState:true,replace:true});</script>
<template><Head title="Laporan Pegawai"/><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4"><div class="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h1 class="text-2xl font-black">Laporan Pegawai</h1><p class="text-sm font-medium text-slate-500">Ringkasan kehadiran dan kedisiplinan pegawai per bulan.</p></div><div class="flex items-center gap-2"><CalendarRange class="h-5 w-5 text-pink-500"/><input v-model="month" @change="load" type="month" class="h-10 rounded-xl border bg-white px-4 font-bold dark:bg-slate-900"/></div></div><div class="grid gap-4 md:grid-cols-3"><div class="rounded-3xl bg-pink-500 p-5 text-white"><p class="text-[10px] font-black uppercase tracking-widest text-white/70">Jumlah Pegawai</p><p class="text-3xl font-black">{{rows.length}}</p></div><div class="rounded-3xl bg-emerald-500 p-5 text-white"><p class="text-[10px] font-black uppercase tracking-widest text-white/70">Total Hari Hadir</p><p class="text-3xl font-black">{{rows.reduce((a,x)=>a+Number(x.presentDays),0)}}</p></div><div class="rounded-3xl bg-amber-500 p-5 text-white"><p class="text-[10px] font-black uppercase tracking-widest text-white/70">Total Keterlambatan</p><p class="text-3xl font-black">{{rows.reduce((a,x)=>a+Number(x.lateDays),0)}}</p></div></div><section class="overflow-hidden rounded-3xl bg-white shadow-sm dark:bg-slate-900"><header class="flex items-center gap-2 border-b p-6 dark:border-slate-800"><FileSpreadsheet class="h-5 w-5 text-pink-500"/><h2 class="font-black">Rekap Bulanan</h2></header><table class="w-full text-left text-sm"><thead><tr class="border-b text-[10px] uppercase tracking-widest text-slate-500 dark:border-slate-800"><th class="p-4 pl-7">Pegawai</th><th>Peran</th><th class="text-center">Hari Hadir</th><th class="text-center">Terlambat</th><th class="text-center">Belum Check-out</th></tr></thead><tbody><tr v-for="x in rows" class="border-b last:border-0 dark:border-slate-800"><td class="p-4 pl-7 font-black">{{x.fullName}}</td><td><span class="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-bold dark:bg-slate-800">{{x.role}}</span></td><td class="text-center"><span class="inline-flex items-center gap-1 font-black text-emerald-600"><UserCheck class="h-4 w-4"/>{{x.presentDays}}</span></td><td class="text-center"><span class="inline-flex items-center gap-1 font-black text-amber-600"><ClockAlert class="h-4 w-4"/>{{x.lateDays}}</span></td><td class="text-center font-black text-rose-600">{{x.incompleteDays}}</td></tr></tbody></table></section></main></AppLayout></template>
